const _projectRecords: Map<string, number[]> = new Map();
const _builderRecords: Map<string, number[]> = new Map();

// --- Per-type helpers ---
function getTypeKey(
  propertyType: string,
): "apartment" | "villa" | "plot" | "commercial" {
  const t = propertyType.toLowerCase();
  if (t === "villa") return "villa";
  if (t === "plot" || t === "land") return "plot";
  if (t === "commercial") return "commercial";
  return "apartment";
}

function getDatasetForType(
  type: "apartment" | "villa" | "plot" | "commercial",
): TrainingRecord[] {
  if (type === "villa") return _datasetVilla;
  if (type === "plot") return _datasetPlot;
  if (type === "commercial") return _datasetCommercial;
  return _datasetApartment;
}

function getModelForType(
  type: "apartment" | "villa" | "plot" | "commercial",
): LinearRegressionModel | null {
  if (type === "villa") return _modelVilla;
  if (type === "plot") return _modelPlot;
  if (type === "commercial") return _modelCommercial;
  return _modelApartment;
}

function setModelForType(
  type: "apartment" | "villa" | "plot" | "commercial",
  model: LinearRegressionModel,
) {
  if (type === "villa") {
    _modelVilla = model;
    return;
  }
  if (type === "plot") {
    _modelPlot = model;
    return;
  }
  if (type === "commercial") {
    _modelCommercial = model;
    return;
  }
  _modelApartment = model;
}

function cleanRecords(records: TrainingRecord[]): TrainingRecord[] {
  return records.filter(
    (r) => r.pricePerSqft >= 3000 && r.pricePerSqft <= 30000,
  );
}

function getLocalityRealCount(
  localityKey: string,
  dataset: TrainingRecord[],
  localityMap: Record<string, number>,
): number {
  const idx = localityMap[localityKey];
  if (idx === undefined) return 0;
  return dataset.filter((r) => r.localityIndex === idx && r.source === "real")
    .length;
}

export function getDataDensityLabel(
  locality: string,
  propertyType: string,
): { label: string; count: number; level: "low" | "medium" | "high" } {
  const typeKey = getTypeKey(propertyType);
  const dataset = getDatasetForType(typeKey);
  const model = getModelForType(typeKey);
  if (!model) return { label: "Low data density", count: 0, level: "low" };
  const count = getLocalityRealCount(
    locality.toLowerCase(),
    dataset,
    model.localityMap,
  );
  if (count >= 15) return { label: "High data density", count, level: "high" };
  if (count >= 5)
    return { label: "Medium data density", count, level: "medium" };
  return { label: "Low data density", count, level: "low" };
}

/**
 * Returns a locality-learning weight adjustment multiplier.
 * If >= 5 real records exist for this locality, the AI model gives higher
 * weight to those and reduces global dataset influence.
 */
/**
 * Returns the average price per sqft computed from real sale records for a locality+type.
 * Returns null if no real records exist.
 */
export function getLocalityAveragePricePerSqft(
  locality: string,
  propertyType: string,
): { avgPrice: number; count: number } | null {
  ensureInitialized();
  const typeKey = getTypeKey(propertyType);
  const dataset = getDatasetForType(typeKey);
  const model = getModelForType(typeKey);
  if (!model) return null;
  const localityKey = locality.toLowerCase();
  const idx = model.localityMap[localityKey];
  if (idx === undefined) return null;
  const realRecords = dataset.filter(
    (r) => r.localityIndex === idx && r.source === "real",
  );
  if (realRecords.length === 0) return null;
  const avg = Math.round(
    realRecords.reduce((s, r) => s + r.pricePerSqft, 0) / realRecords.length,
  );
  return { avgPrice: avg, count: realRecords.length };
}

/**
 * @deprecated Use getLocalityAveragePricePerSqft + blendWithLocalityData in valuationEngine instead.
 * Kept for backward compatibility.
 */
export function getLocalityWeightAdjustment(
  locality: string,
  propertyType: string,
): number {
  const density = getDataDensityLabel(locality, propertyType);
  if (density.count >= 10) return 1.04;
  if (density.count >= 5) return 1.02;
  return 1.0;
}

