export function initAIModel(): LinearRegressionModel {
  // Load any user-submitted records from localStorage before training
  let userSalesRecords: RealSaleRecord[] = [];
  try {
    const stored = localStorage.getItem("valubrix_user_sales");
    if (stored) {
      const parsed: Array<{
        locality: string;
        sqft: number;
        propertyType: string;
        soldPrice: number;
        timestamp: number;
      }> = JSON.parse(stored);
      userSalesRecords = parsed.map((r) => ({
        locality: r.locality,
        type: r.propertyType,
        sqft: r.sqft,
        soldPrice: r.soldPrice,
        dataType: "real" as const,
      }));
    }
  } catch (_e) {
    // localStorage unavailable — skip
  }

  // Step 1: Build locality map from both builder and real sale data
  const allLocalities = [
    ...BUILDER_SEED_DATA.map((d) => ({ locality: d.locality })),
    ...REAL_SALE_SEED_DATA.map((d) => ({ locality: d.locality })),
  ];
  const localityMap: Record<string, number> = {};
  let idx = 0;
  for (const { locality } of allLocalities) {
    const key = locality.toLowerCase();
    if (!(key in localityMap)) localityMap[key] = idx++;
  }

  // Step 2: Builder records (weight = 1x)
  const builderRecords: TrainingRecord[] = BUILDER_SEED_DATA.map((d) => ({
    sqft: d.sqft,
    localityIndex: localityMap[d.locality.toLowerCase()] ?? 0,
    propertyTypeIndex: PROPERTY_TYPE_MAP[d.type] ?? 0,
    demandScore: d.demand,
    metroDistance: d.metro,
    infraScore: d.infra,
    pastAvgPrice: d.pastPrice,
    pricePerSqft: d.pricePerSqft,
    source: "builder" as DataSource,
  }));

  // Step 3: Real sale records (weight = 3x) — derived from actual sold prices
  // demandScore/metro/infra use locality-aware defaults; pastAvgPrice = pricePerSqft * 0.9
  const allRealSaleData = [...REAL_SALE_SEED_DATA, ...userSalesRecords];
  const realRecords: TrainingRecord[] = allRealSaleData.map((d) => {
    const pps = Math.round(d.soldPrice / d.sqft);
    const locKey = d.locality.toLowerCase();
    const locIdx = localityMap[locKey] ?? 0;
    // Locality-based demand score: high-demand areas get higher score
    const demandMap: Record<string, number> = {
      hebbal: 85,
      thanisandra: 78,
      yelahanka: 72,
      jakkur: 75,
      "sahakara nagar": 80,
      "hennur road": 70,
      devanahalli: 65,
      bagalur: 60,
      nagavara: 82,
      "kalyan nagar": 78,
      "hbr layout": 76,
      "hrbr layout": 76,
      "yelahanka new town": 70,
      "bellary road": 75,
      "thanisandra road": 77,
      "jakkur plantation": 72,
      "manyata tech park": 85,
      rajanukunte: 60,
      "ivc road": 58,
      chikkajala: 55,
      sadahalli: 55,
      "doddaballapur road": 55,
      "aerospace park": 62,
      "bagalur main road": 58,
      chikkagubbi: 65,
      narayanapura: 68,
      kothanur: 65,
      "hennur gardens": 72,
      kogilu: 65,
      "kogilu cross": 66,
    };
    const demand = demandMap[locKey] ?? 65;
    return {
      sqft: d.sqft,
      localityIndex: locIdx,
      propertyTypeIndex: PROPERTY_TYPE_MAP[d.type] ?? 0,
      demandScore: demand,
      metroDistance: 8, // conservative default for North Bangalore
      infraScore: 70,
      pastAvgPrice: Math.round(pps * 0.9),
      pricePerSqft: pps,
      source: "real" as DataSource,
    };
  });

  // Step 4: Split by property type and train separate models
  const allRecords = [...builderRecords, ...realRecords];

  const splitAndTrain = (
    typeKeys: string[],
  ): {
    weights: number[];
    mae: number;
    rmse: number;
    records: TrainingRecord[];
  } => {
    const typeIndices = typeKeys.map((k) => PROPERTY_TYPE_MAP[k] ?? 0);
    const filtered = cleanRecords(
      allRecords.filter((r) => typeIndices.includes(r.propertyTypeIndex)),
    );
    if (filtered.length < 3) {
      return {
        weights: new Array(8).fill(0),
        mae: 9999,
        rmse: 9999,
        records: [],
      };
    }
    const { weights, mae, rmse } = trainWeightedLinearRegression(filtered);
    return { weights, mae, rmse, records: filtered };
  };

  const aptResult = splitAndTrain(["flat", "apartment"]);
  const villaResult = splitAndTrain(["villa"]);
  const plotResult = splitAndTrain(["plot"]);

  _datasetApartment.push(...aptResult.records);
  _datasetVilla.push(...villaResult.records);
  _datasetPlot.push(...plotResult.records);

  // ── South Bangalore 700 records — append to per-type datasets ───────────────
  // Strictly segregated: apartments→_datasetApartment, villas→_datasetVilla, plots→_datasetPlot
  // Carpet area records use normalizedAreaSqft for PSF calculation (SBA normalization)
  // Distress records go to _distressPool (excluded from training)
  // Design-Exclusive go to _designExclusivePool (excluded from outlier filtering)

  function appendSouthRecord(
    rec: SouthBangaloreRecord,
    typeKey: "apartment" | "villa" | "plot",
  ): void {
    // Route distress to separate pool — do NOT add to main training
    if (rec.isDistress) {
      _distressPool.push({
        locality: rec.locality,
        type: typeKey,
        sqft: rec.areaSqft,
        soldPrice: rec.soldPrice,
        builder: rec.builder,
        project: rec.project,
        region: "south",
      });
      return;
    }
    // Route Design-Exclusive to separate pool — but ALSO add to training (not filtered)
    if (rec.themeTier === "Design-Exclusive") {
      _designExclusivePool.push({
        locality: rec.locality,
        type: typeKey,
        sqft: rec.areaSqft,
        soldPrice: rec.soldPrice,
        builder: rec.builder,
        project: rec.project,
        region: "south",
      });
    }
    // Use SBA-normalized area for PSF calculation
    const effectiveSqft = getEffectiveArea(rec);
    const pps = Math.round(rec.soldPrice / effectiveSqft);
    if (pps < 1500 || pps > 50000) return; // broad south Bangalore price guard

    const locKey = rec.locality.toLowerCase();
    const locIdx =
      localityMap[locKey] ??
      (() => {
        const newIdx = Object.keys(localityMap).length;
        localityMap[locKey] = newIdx;
        return newIdx;
      })();

    // South demand scores derived from locality tier
    const southDemandMap: Record<string, number> = {
      "kanakapura rd": 80,
      "kanakapura road": 80,
      "bannerghatta rd": 75,
      "bannerghatta road": 75,
      "electronic city": 78,
      "electronic city p1": 80,
      "electronic city p2": 75,
      "begur rd": 72,
      "begur road": 72,
      begur: 70,
      "jp nagar": 82,
      "jp nagar 9th phase": 82,
      "jp nagar 8th phase": 80,
      "jp nagar 7th phase": 80,
      "sarjapur rd": 78,
      "sarjapur road": 78,
      "sarjapur rd south": 78,
      "sarjapur south": 76,
      hulimavu: 72,
      gottigere: 68,
      chandapura: 62,
      jigani: 58,
      anekal: 52,
      sompura: 50,
      "huskur rd": 52,
      uttarahalli: 70,
      talaghattapura: 62,
      attibele: 55,
      padmanabhanagar: 80,
      anjanapura: 68,
      konanakunte: 70,
      konankunte: 70,
      bommasandra: 60,
      "hosur road": 70,
      "hosa road": 70,
      akshayanagar: 72,
      "btm layout": 84,
      binnypet: 78,
      kaggalipura: 60,
      bannerghatta: 74,
      sarjapur: 75,
      "sarjapur rd (s)": 76,
      "hennur road": 70,
      devanahalli: 62,
    };
    const demand = southDemandMap[locKey] ?? 65;
    const metroDistance = 8; // conservative south Bangalore default

    const trainingRecord: TrainingRecord = {
      sqft: effectiveSqft,
      localityIndex: locIdx,
      propertyTypeIndex: PROPERTY_TYPE_MAP[typeKey] ?? 0,
      demandScore: demand,
      metroDistance,
      infraScore: 68,
      pastAvgPrice: Math.round(pps * 0.9),
      pricePerSqft: pps,
      source: "real" as DataSource,
    };

    // Update project/builder maps
    if (rec.project?.trim()) {
      const pk = makeProjectKey(rec.project, typeKey);
      if (!_projectRecords.has(pk)) _projectRecords.set(pk, []);
      _projectRecords.get(pk)!.push(pps);
    }
    if (
      rec.builder?.trim() &&
      rec.builder.toLowerCase() !== "local" &&
      rec.builder.toLowerCase() !== "owner"
    ) {
      const bk = makeBuilderKey(rec.builder, typeKey);
      if (!_builderRecords.has(bk)) _builderRecords.set(bk, []);
      _builderRecords.get(bk)!.push(pps);
    }

    if (typeKey === "apartment") _datasetApartment.push(trainingRecord);
    else if (typeKey === "villa") _datasetVilla.push(trainingRecord);
    else _datasetPlot.push(trainingRecord);
  }

  for (const rec of southBangaloreApartments)
    appendSouthRecord(rec, "apartment");
  for (const rec of southBangaloreVillas) appendSouthRecord(rec, "villa");
  for (const rec of southBangalorePlots) appendSouthRecord(rec, "plot");

  // ── North Bangalore 1800+ records — append to per-type datasets ─────────────
  // Strictly segregated by type. Recency weights via month field (month=10 = 5x).
  // Carpet area records normalized to SBA before PSF calculation.
  function appendNorthRecord(rec: NBTrainingRecord): void {
    if (rec.isOutlier) return;

    // SBA normalization: if carpet, divide by 0.75 to get SBA
    const effectiveSqft =
      rec.areaType === "Carpet" || rec.isCarpet === true
        ? rec.areaSqft / 0.75
        : rec.areaSqft;
    const pps =
      effectiveSqft > 0 ? Math.round(rec.soldPrice / effectiveSqft) : 0;
    if (pps < 2000 || pps > 35000) return;

    const locKey = rec.locality.toLowerCase();
    const locIdx =
      localityMap[locKey] ??
      (() => {
        const newIdx = Object.keys(localityMap).length;
        localityMap[locKey] = newIdx;
        return newIdx;
      })();

    // Demand scores for NB localities
    const nbDemandMap: Record<string, number> = {
      hebbal: 85,
      jakkur: 75,
      thanisandra: 78,
      hennur: 70,
      "hennur road": 70,
      bagalur: 60,
      devanahalli: 65,
      yelahanka: 72,
      rajankunte: 60,
      kogilu: 65,
      vidyaranyapura: 65,
      "airport road": 62,
    };
    const demand = nbDemandMap[locKey] ?? 65;

    const typeKey =
      rec.propertyType === "apartment"
        ? "apartment"
        : rec.propertyType === "villa"
          ? "villa"
          : rec.propertyType === "commercial"
            ? "commercial"
            : "plot";

    const propTypeIdx =
      PROPERTY_TYPE_MAP[typeKey === "commercial" ? "commercial" : typeKey] ?? 0;

    const trainingRecord: TrainingRecord = {
      sqft: effectiveSqft,
      localityIndex: locIdx,
      propertyTypeIndex: propTypeIdx,
      demandScore: demand,
      metroDistance: 12, // conservative NB default
      infraScore: 68,
      pastAvgPrice: Math.round(pps * 0.9),
      pricePerSqft: pps,
      source: "real" as DataSource,
      month: rec.month,
    };

    if (rec.project?.trim()) {
      const pk = makeProjectKey(rec.project, typeKey);
      if (!_projectRecords.has(pk)) _projectRecords.set(pk, []);
      _projectRecords.get(pk)!.push(pps);
    }
    if (
      rec.builder?.trim() &&
      rec.builder.toLowerCase() !== "local" &&
      rec.builder.toLowerCase() !== "owner"
    ) {
      const bk = makeBuilderKey(rec.builder, typeKey);
      if (!_builderRecords.has(bk)) _builderRecords.set(bk, []);
      _builderRecords.get(bk)!.push(pps);
    }

    if (typeKey === "apartment") _datasetApartment.push(trainingRecord);
    else if (typeKey === "villa") _datasetVilla.push(trainingRecord);
    else if (typeKey === "commercial") _datasetCommercial.push(trainingRecord);
    else _datasetPlot.push(trainingRecord);
  }

  const nbApartments = getNorthBangaloreData("apartment");
  const nbVillas = getNorthBangaloreData("villa");
  const nbPlots = getNorthBangaloreData("plot");
  const nbCommercial = getNorthBangaloreData("commercial");

  for (const rec of nbApartments) appendNorthRecord(rec);
  for (const rec of nbVillas) appendNorthRecord(rec);
  for (const rec of nbPlots) appendNorthRecord(rec);
  for (const rec of nbCommercial) appendNorthRecord(rec);

  console.log(
    `[ValuBrix] North Bangalore training: apartments=${nbApartments.length} villas=${nbVillas.length} plots=${nbPlots.length} commercial=${nbCommercial.length}`,
  );

  console.log(
    `[ValuBrix] South Bangalore training: apartments=${southBangaloreApartments.length} villas=${southBangaloreVillas.length} plots=${southBangalorePlots.length} | designExclusive=${_designExclusivePool.length} | distress=${_distressPool.length}`,
  );

  const builderAptCount = aptResult.records.filter(
    (r) => r.source === "builder",
  ).length;
  const realAptCount = aptResult.records.filter(
    (r) => r.source === "real",
  ).length;
  _modelApartment = {
    weights: aptResult.weights,
    featureNames: FEATURE_NAMES,
    mae: aptResult.mae,
    rmse: aptResult.rmse,
    trainedAt: Date.now(),
    sampleCount: aptResult.records.length,
    builderCount: builderAptCount,
    realCount: realAptCount,
    localityMap,
  };

  const builderVillaCount = villaResult.records.filter(
    (r) => r.source === "builder",
  ).length;
  const realVillaCount = villaResult.records.filter(
    (r) => r.source === "real",
  ).length;
  _modelVilla = {
    weights: villaResult.weights,
    featureNames: FEATURE_NAMES,
    mae: villaResult.mae,
    rmse: villaResult.rmse,
    trainedAt: Date.now(),
    sampleCount: villaResult.records.length,
    builderCount: builderVillaCount,
    realCount: realVillaCount,
    localityMap,
  };

  const builderPlotCount = plotResult.records.filter(
    (r) => r.source === "builder",
  ).length;
  const realPlotCount = plotResult.records.filter(
    (r) => r.source === "real",
  ).length;
  _modelPlot = {
    weights: plotResult.weights,
    featureNames: FEATURE_NAMES,
    mae: plotResult.mae,
    rmse: plotResult.rmse,
    trainedAt: Date.now(),
    sampleCount: plotResult.records.length,
    builderCount: builderPlotCount,
    realCount: realPlotCount,
    localityMap,
  };

  return _modelApartment!;
}

export function getModel(): LinearRegressionModel {
  if (!_modelApartment) initAIModel();
  return _modelApartment!;
}

function ensureInitialized() {
  if (!_modelApartment) initAIModel();
}

export interface PredictionInput {
  locality: string;
  sqft: number;
  propertyType: string;
  demandScore: number;
  metroDistance: number;
  infraScore: number;
  pastAvgPrice: number;
}

export interface PredictionResult {
  pricePerSqft: number;
  confidence: "high" | "medium" | "low";
  usedAI: boolean;
  aiError: number;
  explanation: string[];
  modelInfo: {
    builderRecords: number;
    realRecords: number;
    realDataDominance: number; // 0-100% — how much real data influences model
  };
  dataDensity: {
    label: string;
    count: number;
    level: "low" | "medium" | "high";
  };
}

export function predictPricePerSqft(
  input: PredictionInput,
  fallbackPrice: number,
): PredictionResult {
  ensureInitialized();
  const typeKey = getTypeKey(input.propertyType);
  const model = getModelForType(typeKey);
  const dataset = getDatasetForType(typeKey);

  if (!model) {
    return {
      pricePerSqft: fallbackPrice,
      confidence: "low",
      usedAI: false,
      aiError: 9999,
      explanation: ["Model not yet trained for this property type"],
      modelInfo: { builderRecords: 0, realRecords: 0, realDataDominance: 0 },
      dataDensity: { label: "Low data density", count: 0, level: "low" },
    };
  }

  const localityKey = input.locality.toLowerCase();
  const localityIndex = model.localityMap[localityKey];

  // Count real records for this specific type + locality
  const realCount =
    localityIndex !== undefined
      ? dataset.filter(
          (r) => r.localityIndex === localityIndex && r.source === "real",
        ).length
      : 0;

  // Data density based on per-type, per-locality real record count
  const densityLevel =
    realCount >= 15 ? "high" : realCount >= 5 ? "medium" : "low";
  const densityLabel =
    realCount >= 15
      ? "High data density"
      : realCount >= 5
        ? "Medium data density"
        : "Low data density";
  const dataDensity = {
    label: densityLabel,
    count: realCount,
    level: densityLevel as "low" | "medium" | "high",
  };

  const totalW =
    model.builderCount * BUILDER_DATA_WEIGHT +
    model.realCount * REAL_DATA_WEIGHT;
  const realDominance =
    totalW > 0
      ? Math.round((model.realCount * REAL_DATA_WEIGHT * 100) / totalW)
      : 0;

  // If sparse (<5 real records for this type in this locality), use nearby locality blend
  if (realCount < 5) {
    const nearbyLocalities = NEARBY_LOCALITIES[localityKey] || [];
    const nearbyPrices: number[] = [];
    for (const nearby of nearbyLocalities) {
      const nearbyIdx = model.localityMap[nearby];
      if (nearbyIdx === undefined) continue;
      const nearbyRecords = dataset.filter(
        (r) => r.localityIndex === nearbyIdx && r.source === "real",
      );
      if (nearbyRecords.length > 0) {
        const avg =
          nearbyRecords.reduce((s, r) => s + r.pricePerSqft, 0) /
          nearbyRecords.length;
        nearbyPrices.push(avg);
      }
    }

    if (nearbyPrices.length > 0) {
      const nearbyAvg =
        nearbyPrices.reduce((s, p) => s + p, 0) / nearbyPrices.length;
      // Blend: 40% comparables fallback, 60% nearby average
      const blendedPrice = Math.round(fallbackPrice * 0.4 + nearbyAvg * 0.6);
      return {
        pricePerSqft: blendedPrice,
        confidence: "low",
        usedAI: false,
        aiError: model.mae,
        explanation: [
          `Low data density for ${typeKey}s in ${input.locality} (${realCount} real records)`,
          `Using nearby locality data blend (${nearbyLocalities.slice(0, 2).join(", ")})`,
          "Submit sold prices to improve accuracy",
        ],
        modelInfo: {
          builderRecords: model.builderCount,
          realRecords: model.realCount,
          realDataDominance: realDominance,
        },
        dataDensity,
      };
    }

    // Pure fallback
    return {
      pricePerSqft: fallbackPrice,
      confidence: "low",
      usedAI: false,
      aiError: model.mae,
      explanation: [
        `Insufficient ${typeKey} data for ${input.locality} (${realCount} real records)`,
        "Using comparables engine",
      ],
      modelInfo: {
        builderRecords: model.builderCount,
        realRecords: model.realCount,
        realDataDominance: realDominance,
      },
      dataDensity,
    };
  }

  // Sufficient data — use AI model
  const features: TrainingRecord = {
    sqft: input.sqft,
    localityIndex: localityIndex ?? 0,
    propertyTypeIndex: PROPERTY_TYPE_MAP[input.propertyType.toLowerCase()] ?? 0,
    demandScore: input.demandScore,
    metroDistance: input.metroDistance,
    infraScore: input.infraScore,
    pastAvgPrice: input.pastAvgPrice,
    pricePerSqft: 0,
    source: "builder",
  };
  const rawPred = dotProduct(recordToFeatures(features), model.weights);
  const pred = Math.max(rawPred, 3000);

  const errorPct = model.mae / (pred || 1);
  const aiConfidence =
    errorPct < 0.08 ? "high" : errorPct < 0.15 ? "medium" : "low";
  // Use data density as primary confidence signal
  const confidence = (
    densityLevel === "high"
      ? aiConfidence === "low"
        ? "medium"
        : aiConfidence
      : densityLevel
  ) as "high" | "medium" | "low";

  const explanation: string[] = [
    `Based on ${realCount} real ${typeKey} transactions in ${input.locality}`,
  ];
  if (input.demandScore > 80) explanation.push("High demand boosting price");
  if (input.metroDistance < 3)
    explanation.push("Metro proximity adding premium");
  if (input.infraScore > 80) explanation.push("Strong infrastructure score");
  if (model.realCount > 0)
    explanation.push(`${realDominance}% real-data influence on model`);

  return {
    pricePerSqft: Math.round(pred),
    confidence,
    usedAI: true,
    aiError: Math.round(model.mae),
    explanation,
    modelInfo: {
      builderRecords: model.builderCount,
      realRecords: model.realCount,
      realDataDominance: realDominance,
    },
    dataDensity,
  };
}

/**
 * Called when a real sale closes.
 * Real data is weighted 3x vs builder data — it dominates model over time.
 */
// Key helpers for project/builder records
function makeProjectKey(project: string, propertyType: string): string {
  return `${project.toLowerCase().trim()}|||${propertyType.toLowerCase().trim()}`;
}
function makeBuilderKey(builder: string, propertyType: string): string {
  return `${builder.toLowerCase().trim()}|||${propertyType.toLowerCase().trim()}`;
}

export function addSaleFeedbackAndRetrain(
  locality: string,
  sqft: number,
  propertyType: string,
  soldPrice: number,
  builder?: string,
  project?: string,
): void {
  ensureInitialized();
  const typeKey = getTypeKey(propertyType);
  const model = getModelForType(typeKey);
  if (!model) return;

  const pps = Math.round(soldPrice / sqft);
  if (pps < 3000 || pps > 30000) return; // data cleaning

  // Store project and builder records for hierarchy learning
  if (project?.trim()) {
    const pk = makeProjectKey(project, propertyType);
    if (!_projectRecords.has(pk)) _projectRecords.set(pk, []);
    _projectRecords.get(pk)!.push(pps);
  }
  if (builder?.trim()) {
    const bk = makeBuilderKey(builder, propertyType);
    if (!_builderRecords.has(bk)) _builderRecords.set(bk, []);
    _builderRecords.get(bk)!.push(pps);
  }

  const localityKey = locality.toLowerCase();
  const localityIndex =
    model.localityMap[localityKey] ?? Object.keys(model.localityMap).length;

  const record: TrainingRecord = {
    sqft,
    localityIndex,
    propertyTypeIndex: PROPERTY_TYPE_MAP[propertyType.toLowerCase()] ?? 0,
    demandScore: 70,
    metroDistance: 8,
    infraScore: 70,
    pastAvgPrice: Math.round(pps * 0.9),
    pricePerSqft: pps,
    source: "real",
  };

  const dataset = getDatasetForType(typeKey);
  dataset.push(record);

  const cleaned = cleanRecords(dataset);
  const { weights, mae, rmse } = trainWeightedLinearRegression(cleaned);
  const newModel: LinearRegressionModel = {
    ...model,
    weights,
    mae,
    rmse,
    trainedAt: Date.now(),
    sampleCount: cleaned.length,
    builderCount: cleaned.filter((r) => r.source === "builder").length,
    realCount: cleaned.filter((r) => r.source === "real").length,
  };
  setModelForType(typeKey, newModel);

  // Debug logging
  const localityCount = getLocalityRealCount(
    localityKey,
    dataset,
    newModel.localityMap,
  );
  console.log(
    `[ValuBrix] ✅ Record saved | locality="${locality}" type="${propertyType}" pps=${pps}`,
  );
  console.log(
    `[ValuBrix] 🔄 Retrain triggered | sampleCount=${newModel.sampleCount} realCount=${newModel.realCount} builderCount=${newModel.builderCount}`,
  );
  console.log(
    `[ValuBrix] 📍 Locality dataset count updated | locality="${locality}" realRecords=${localityCount}`,
  );

  // Persist to localStorage so submissions survive page reloads
  try {
    const stored = localStorage.getItem("valubrix_user_sales");
    const existing: Array<{
      locality: string;
      sqft: number;
      propertyType: string;
      soldPrice: number;
      builder?: string;
      project?: string;
      timestamp: number;
    }> = stored ? JSON.parse(stored) : [];
    existing.push({
      locality,
      sqft,
      propertyType,
      soldPrice,
      builder: builder ?? "",
      project: project ?? "",
      timestamp: Date.now(),
    });
    localStorage.setItem("valubrix_user_sales", JSON.stringify(existing));

    // Auto-trigger corpus retrain every 50 submissions
    if (existing.length > 0 && existing.length % 50 === 0) {
      console.log(
        `[ValuBrix] 🚀 Auto-retrain triggered at ${existing.length} user submissions`,
      );
      // Defer to next tick so current call stack completes first
      setTimeout(() => {
        retrainOnCorpus();
      }, 0);
    }
  } catch (_e) {
    // localStorage unavailable (SSR/private mode) — skip silently
  }
}

export function getModelConfidenceLabel(mae: number, avgPrice: number): string {
  const errorPct = mae / (avgPrice || 1);
  if (errorPct < 0.08) return "High (AI model reliable)";
  if (errorPct < 0.15) return "Medium (AI model learning)";
  return "Low (using comparables fallback)";
}

export function getModelStats(): {
  sampleCount: number;
  builderCount: number;
  realCount: number;
  realDataDominance: number;
  mae: number;
  rmse: number;
  trainedAt: number;
  aptStats: {
    builderCount: number;
    realCount: number;
    sampleCount: number;
    mae: number;
  };
  villaStats: {
    builderCount: number;
    realCount: number;
    sampleCount: number;
    mae: number;
  };
  plotStats: {
    builderCount: number;
    realCount: number;
    sampleCount: number;
    mae: number;
  };
} | null {
  if (!_modelApartment) return null;
  const m = _modelApartment;
  const totalW =
    m.builderCount * BUILDER_DATA_WEIGHT + m.realCount * REAL_DATA_WEIGHT;
  const realDominance =
    totalW > 0
      ? Math.round((m.realCount * REAL_DATA_WEIGHT * 100) / totalW)
      : 0;
  const toStats = (mdl: LinearRegressionModel | null) =>
    mdl
      ? {
          builderCount: mdl.builderCount,
          realCount: mdl.realCount,
          sampleCount: mdl.sampleCount,
          mae: mdl.mae,
        }
      : { builderCount: 0, realCount: 0, sampleCount: 0, mae: 9999 };
  return {
    sampleCount: m.sampleCount,
    builderCount: m.builderCount,
    realCount: m.realCount,
    realDataDominance: realDominance,
    mae: m.mae,
    rmse: m.rmse,
    trainedAt: m.trainedAt,
    aptStats: toStats(_modelApartment),
    villaStats: toStats(_modelVilla),
    plotStats: toStats(_modelPlot),
  };
}

export function getRealDataConfidenceLabel(realDataDominancePct: number): {
  label: string;
  level: "low" | "medium" | "high";
} {
  if (realDataDominancePct < 30)
    return { label: "Low confidence", level: "low" };
  if (realDataDominancePct <= 60)
    return { label: "Medium confidence", level: "medium" };
  return { label: "High confidence", level: "high" };
}

// 24-hour batch retrain — keeps model fresh even without new sales
if (typeof window !== "undefined") {
  setInterval(
    () => {
      const retrainType = (type: "apartment" | "villa" | "plot") => {
        const dataset = getDatasetForType(type);
        const model = getModelForType(type);
        if (dataset.length > 0 && model) {
          const cleaned = cleanRecords(dataset);
          const { weights, mae, rmse } = trainWeightedLinearRegression(cleaned);
          setModelForType(type, {
            ...model,
            weights,
            mae,
            rmse,
            trainedAt: Date.now(),
          });
        }
      };
      retrainType("apartment");
      retrainType("villa");
      retrainType("plot");
    },
    24 * 60 * 60 * 1000,
  );
}

export interface LocalityStats {
  locality: string;
  recordCount: number;
  avgPricePerSqft: number;
  minPricePerSqft: number;
  maxPricePerSqft: number;
  propertyTypes: string[];
}

export function getLocalityDistribution(): LocalityStats[] {
  const map: Record<string, { prices: number[]; types: Set<string> }> = {};
  for (const r of REAL_SALE_SEED_DATA) {
    const ppsf = r.soldPrice / r.sqft;
    if (!map[r.locality]) map[r.locality] = { prices: [], types: new Set() };
    map[r.locality].prices.push(ppsf);
    map[r.locality].types.add(r.type);
  }
  return Object.entries(map)
    .map(([locality, { prices, types }]) => ({
      locality,
      recordCount: prices.length,
      avgPricePerSqft: Math.round(
        prices.reduce((a, b) => a + b, 0) / prices.length,
      ),
      minPricePerSqft: Math.round(Math.min(...prices)),
      maxPricePerSqft: Math.round(Math.max(...prices)),
      propertyTypes: Array.from(types),
    }))
    .sort((a, b) => b.recordCount - a.recordCount);
}

/** Returns project-level average price per sqft and record count */
export function getProjectAveragePricePerSqft(
  project: string,
  propertyType: string,
): { avgPrice: number; count: number } | null {
  if (!project || !project.trim()) return null;
  const key = makeProjectKey(project, propertyType);
  const records = _projectRecords.get(key);
  if (!records || records.length === 0) return null;
  // Remove top/bottom 10% outliers if enough data
  const sorted = [...records].sort((a, b) => a - b);
  const trimCount = sorted.length >= 10 ? Math.floor(sorted.length * 0.1) : 0;
  const trimmed = sorted.slice(trimCount, sorted.length - trimCount);
  const avg = Math.round(trimmed.reduce((s, v) => s + v, 0) / trimmed.length);
  return { avgPrice: avg, count: records.length };
}

/** Returns builder-level average price per sqft and record count */
export function getBuilderAveragePricePerSqft(
  builder: string,
  propertyType: string,
): { avgPrice: number; count: number } | null {
  if (!builder || !builder.trim()) return null;
  const key = makeBuilderKey(builder, propertyType);
  const records = _builderRecords.get(key);
  if (!records || records.length === 0) return null;
  const avg = Math.round(records.reduce((s, v) => s + v, 0) / records.length);
  return { avgPrice: avg, count: records.length };
}

/** Returns variance status for a set of price records */
export function getVarianceStatus(records: number[]): {
  isHighVariance: boolean;
  cv: number;
} {
  if (records.length < 3) return { isHighVariance: false, cv: 0 };
  const mean = records.reduce((s, v) => s + v, 0) / records.length;
  const variance =
    records.reduce((s, v) => s + (v - mean) ** 2, 0) / records.length;
  const stdDev = Math.sqrt(variance);
  const cv = stdDev / mean;
  return { isHighVariance: cv > 0.25, cv: Math.round(cv * 100) / 100 };
}

// ─── Continuous Learning — Corpus Retrain ────────────────────────────────────────────
//
// Re-derives locality PSF medians, variance, and builder coefficients from the
// entire training corpus (seed data + aiLearning submissions).
// Triggered automatically when aiLearning submissions count is a multiple of 50.
// Returns training diagnostics.

export interface RetrainResult {
  trainedSamples: number;
  localitiesTouched: number;
  rmsError: number;
}

/**
 * Retrain all three per-type models from the full corpus (builder seed + user submissions).
 * Updates in-memory learned coefficients.
 * Call periodically or after bulk data additions.
 */
export function retrainOnCorpus(): RetrainResult {
  ensureInitialized();

  // Re-initialize from scratch using the full data (seed + localStorage user submissions)
  const newModel = initAIModel();

  // Collect all user-submitted records from localStorage
  let userSubmissionCount = 0;
  try {
    const stored = localStorage.getItem("valubrix_user_sales");
    if (stored) {
      const parsed: Array<{
        locality: string;
        sqft: number;
        propertyType: string;
        soldPrice: number;
        builder?: string;
        project?: string;
        timestamp?: number;
      }> = JSON.parse(stored);
      userSubmissionCount = parsed.length;

      // Re-add all user submissions at higher weight
      for (const r of parsed) {
        const pps = Math.round(r.soldPrice / r.sqft);
        if (pps < 3000 || pps > 30000) continue;

        // Update project/builder maps
        if (r.project?.trim()) {
          const pk = makeProjectKey(r.project, r.propertyType);
          if (!_projectRecords.has(pk)) _projectRecords.set(pk, []);
          _projectRecords.get(pk)!.push(pps);
        }
        if (r.builder?.trim()) {
          const bk = makeBuilderKey(r.builder, r.propertyType);
          if (!_builderRecords.has(bk)) _builderRecords.set(bk, []);
          _builderRecords.get(bk)!.push(pps);
        }
      }
    }
  } catch (_e) {
    // localStorage unavailable — skip silently
  }

  // Re-run weighted regression on all three type datasets
  const retrainType = (type: "apartment" | "villa" | "plot") => {
    const dataset = getDatasetForType(type);
    const model = getModelForType(type);
    if (!model || dataset.length === 0) return;
    const cleaned = cleanRecords(dataset);
    if (cleaned.length === 0) return;
    const { weights, mae, rmse } = trainWeightedLinearRegression(cleaned);
    setModelForType(type, {
      ...model,
      weights,
      mae,
      rmse,
      trainedAt: Date.now(),
      sampleCount: cleaned.length,
      builderCount: cleaned.filter((r) => r.source === "builder").length,
      realCount: cleaned.filter((r) => r.source === "real").length,
    });
  };

  retrainType("apartment");
  retrainType("villa");
  retrainType("plot");

  // Count unique localities touched across all datasets
  const touchedLocalities = new Set<number>();
  for (const r of [..._datasetApartment, ..._datasetVilla, ..._datasetPlot]) {
    touchedLocalities.add(r.localityIndex);
  }

  const totalSamples =
    (_modelApartment?.sampleCount ?? 0) +
    (_modelVilla?.sampleCount ?? 0) +
    (_modelPlot?.sampleCount ?? 0);

  const avgRmse =
    ((_modelApartment?.rmse ?? 0) +
      (_modelVilla?.rmse ?? 0) +
      (_modelPlot?.rmse ?? 0)) /
    3;

  console.log(
    `[ValuBrix] 🔄 retrainOnCorpus | samples=${totalSamples} localitiesTouched=${touchedLocalities.size} userSubmissions=${userSubmissionCount} avgRMSE=${Math.round(avgRmse)}`,
  );

  // Suppress unused variable warning
  void newModel;

  return {
    trainedSamples: totalSamples,
    localitiesTouched: touchedLocalities.size,
    rmsError: Math.round(avgRmse),
  };
}

/**
 * Auto-trigger retrainOnCorpus every time a multiple of 50 user submissions is reached.
 * Called from addSaleFeedbackAndRetrain after each new submission.
 */
export function maybeAutoRetrain(): void {
  try {
    const stored = localStorage.getItem("valubrix_user_sales");
    if (!stored) return;
    const parsed: unknown[] = JSON.parse(stored);
    if (parsed.length > 0 && parsed.length % 50 === 0) {
      console.log(
        `[ValuBrix] 🚀 Auto-retrain triggered at ${parsed.length} user submissions`,
      );
      retrainOnCorpus();
    }
  } catch (_e) {
    // localStorage unavailable — skip
  }
}
